"""Finalize a Debian GDB bundle so both public entry points work directly.

Standalone (no MCP required): python3 src/tools/gdb/bundle.py --prefix .external/gdb
The original ELF is preserved as usr/bin/gdb.real. Launchers resolve library
directories at runtime, so moving the bundle does not require regenerating them.
"""

from __future__ import annotations

import argparse
import fcntl
import os
from pathlib import Path
import tempfile


_MARKER = "# Generated by APRE:"
_LAUNCHER = '''#!/bin/sh
# Generated by APRE: relocatable bundled GDB launcher.
set -eu
APRE_GDB_ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/../.." && pwd -P)"
APRE_GDB_LIBS=
for APRE_GDB_DIR in "$APRE_GDB_ROOT"/usr/lib "$APRE_GDB_ROOT"/usr/lib/* \\
                    "$APRE_GDB_ROOT"/lib "$APRE_GDB_ROOT"/lib/* \\
                    "$APRE_GDB_ROOT"/usr/lib64 "$APRE_GDB_ROOT"/lib64; do
    [ -d "$APRE_GDB_DIR" ] || continue
    APRE_GDB_LIBS="${APRE_GDB_LIBS:+$APRE_GDB_LIBS:}$APRE_GDB_DIR"
done
LD_LIBRARY_PATH="$APRE_GDB_LIBS${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
export LD_LIBRARY_PATH
exec "$APRE_GDB_ROOT/usr/bin/gdb.real" "$@"
'''
_ALIAS = '''#!/bin/sh
# Generated by APRE: bundled GDB convenience entry point.
set -eu
APRE_GDB_ROOT="$(CDPATH= cd -- "$(dirname -- "$0")" && pwd -P)"
exec "$APRE_GDB_ROOT/usr/bin/gdb" "$@"
'''


def _is_elf(path: Path) -> bool:
    with path.open("rb") as stream:
        return stream.read(4) == b"\x7fELF"


def _is_generated(path: Path) -> bool:
    with path.open("rb") as stream:
        return _MARKER.encode() in stream.read(256)


def _write_launcher(path: Path, content: str) -> None:
    if path.exists() and path.read_bytes() == content.encode() and os.access(path, os.X_OK):
        return
    fd, temp = tempfile.mkstemp(prefix=".apre-gdb-", dir=path.parent)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            stream.write(content)
            stream.flush()
            os.fchmod(stream.fileno(), 0o755)
        os.replace(temp, path)
    finally:
        if os.path.exists(temp):
            os.unlink(temp)


def prepare_bundle(prefix: str | Path) -> str:
    """Install launchers, preserving the ELF; repeat calls are safe.

    Only package ELFs or APRE-generated launchers may be replaced. Errors are
    reported to the standalone caller; probing can fall back to environment
    injection when the bundle is read-only.
    """
    prefix = Path(prefix).resolve()
    binary = prefix / "usr/bin/gdb"
    real = binary.with_name("gdb.real")
    alias = prefix / "gdb"
    with (prefix / ".apre-gdb.lock").open("a") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        if alias.exists() and not _is_generated(alias):
            raise ValueError("Refusing to replace a non-APRE launcher: %s" % alias)
        if not os.access(binary, os.X_OK):
            raise ValueError("GDB is missing or not executable: %s" % binary)
        if _is_elf(binary):
            if real.exists() and not _is_elf(real):
                raise ValueError("Refusing to replace a non-ELF backup: %s" % real)
            os.replace(binary, real)
            try:
                _write_launcher(binary, _LAUNCHER)
            except OSError:
                os.replace(real, binary)
                raise
        elif _is_generated(binary) and real.is_file() and _is_elf(real):
            _write_launcher(binary, _LAUNCHER)
        else:
            raise ValueError("Not a package ELF or valid APRE launcher: %s" % binary)
        _write_launcher(alias, _ALIAS)
    return str(binary)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--prefix", default=str(Path(__file__).resolve().parents[3] / ".external/gdb"))
    options = parser.parse_args()
    try:
        print(prepare_bundle(options.prefix))
    except (OSError, ValueError) as exc:
        parser.exit(1, "GDB bundle preparation failed: %s\n" % exc)
